import com.comsol.model.*;import com.comsol.model.util.*;
public class EvalDriveResMax{public static void main(String[]a)throws Exception{ModelUtil.initStandalone(true);Model m=ModelUtil.load("m","D:\\comsol_ao_run\\convergence\\Wap_6um_driven_coupled_resonance.mph");try{String[]ds=m.result().dataset().tags();String d=ds[ds.length-1];System.out.println("DATA="+d);m.component("comp1").cpl().create("maxop1","Maximum");m.component("comp1").cpl("maxop1").selection().geom("geom1",3);m.component("comp1").cpl("maxop1").selection().named("selLN");m.result().numerical().create("evalMx","EvalGlobal");m.result().numerical("evalMx").set("data",d);m.result().numerical("evalMx").set("looplevelinput",new String[]{"all"});m.result().numerical("evalMx").set("expr",new String[]{"freq","maxop1(sqrt(abs(u)^2+abs(v)^2+abs(w)^2))","maxop1(abs(solid.eXX))","maxop1(abs(solid.eYY))","maxop1(abs(solid.eZZ))","maxop1(abs(solid.eXY))","maxop1(abs(solid.eYZ))","maxop1(abs(solid.eXZ))"});double[][]r=m.result().numerical("evalMx").getReal();for(int j=0;j<r[0].length;j++)System.out.printf(java.util.Locale.US,"MAX f=%.6f GHz disp=%.6e strain=%.6e,%.6e,%.6e,%.6e,%.6e,%.6e%n",r[0][j]/1e9,r[1][j],r[2][j],r[3][j],r[4][j],r[5][j],r[6][j],r[7][j]);m.result().table().create("tblMx","Table");m.result().numerical("evalMx").set("table","tblMx");m.result().numerical("evalMx").setResult();m.result().table("tblMx").save("D:\\comsol_ao_run\\convergence\\Wap_6um_driven_coupled_resonance_max.csv");}catch(Throwable t){t.printStackTrace(System.out);}finally{ModelUtil.disconnect();}}}


